use zigzag::zigzag;

#[test]
fn test_single_row() {
    assert_eq!(zigzag("ABCDE", 1), "ABCDE");
}

#[test]
fn test_all_fit_one_column() {
    assert_eq!(zigzag("AB", 5), "AB");
}

#[test]
fn test_three_rows() {
    assert_eq!(zigzag("PAYPALISHIRING", 3), "PAHNAPLSIIGYIR");
}

#[test]
fn test_four_rows() {
    assert_eq!(zigzag("PAYPALISHIRING", 4), "PINALSIGYAHRPI");
}
